package ch.logixisland.anuto.business.control;

import java.util.Iterator;

import ch.logixisland.anuto.business.level.TowerAging;
import ch.logixisland.anuto.business.manager.GameManager;
import ch.logixisland.anuto.business.score.ScoreBoard;
import ch.logixisland.anuto.engine.logic.GameEngine;
import ch.logixisland.anuto.entity.Entity;
import ch.logixisland.anuto.entity.Types;
import ch.logixisland.anuto.entity.plateau.Plateau;
import ch.logixisland.anuto.entity.tower.Tower;
import ch.logixisland.anuto.entity.tower.TowerFactory;
import ch.logixisland.anuto.util.math.vector.Vector2;

public class TowerInserter {

    private final GameEngine mGameEngine;
    private final GameManager mGameManager;
    private final TowerFactory mTowerFactory;
    private final TowerSelector mTowerSelector;
    private final TowerAging mTowerAging;
    private final ScoreBoard mScoreBoard;

    private Tower mInsertedTower;
    private Plateau mCurrentPlateau;

    public TowerInserter(GameEngine gameEngine, GameManager gameManager, TowerFactory towerFactory,
                         TowerSelector towerSelector, TowerAging towerAging, ScoreBoard scoreBoard) {
        mGameEngine = gameEngine;
        mGameManager = gameManager;
        mTowerFactory = towerFactory;
        mTowerSelector = towerSelector;
        mTowerAging = towerAging;
        mScoreBoard = scoreBoard;
    }

    public void insertTower(final String towerName) {
        if (mGameEngine.isThreadChangeNeeded()) {
            mGameEngine.post(new Runnable() {
                @Override
                public void run() {
                    insertTower(towerName);
                }
            });
            return;
        }

        if (mInsertedTower == null && !mGameManager.isGameOver()) {
            showTowerLevels();
            mInsertedTower = mTowerFactory.createTower(towerName);
        }
    }

    public void setPosition(final Vector2 position) {
        if (mGameEngine.isThreadChangeNeeded()) {
            mGameEngine.post(new Runnable() {
                @Override
                public void run() {
                    setPosition(position);
                }
            });
            return;
        }

        if (mInsertedTower != null) {
            Plateau closestPlateau = mGameEngine.get(Types.PLATEAU)
                    .cast(Plateau.class)
                    .filter(Plateau.unoccupied())
                    .min(Entity.distanceTo(position));

            if (closestPlateau != null) {
                if (mCurrentPlateau == null) {
                    mGameEngine.add(mInsertedTower);
                    mTowerSelector.selectTower(mInsertedTower);
                }

                mCurrentPlateau = closestPlateau;
                mInsertedTower.setPosition(mCurrentPlateau.getPosition());
            } else {
                cancel();
            }
        }
    }

    public void buyTower() {
        if (mGameEngine.isThreadChangeNeeded()) {
            mGameEngine.post(new Runnable() {
                @Override
                public void run() {
                    buyTower();
                }
            });
            return;
        }

        if (mInsertedTower != null && mCurrentPlateau != null) {
            mInsertedTower.setEnabled(true);
            mCurrentPlateau.setOccupant(mInsertedTower);

            mScoreBoard.takeCredits(mInsertedTower.getValue());
            mTowerAging.ageTower(mInsertedTower);

            mTowerSelector.selectTower(null);
            hideTowerLevels();

            mCurrentPlateau = null;
            mInsertedTower = null;
        }
    }

    public void cancel() {
        if (mGameEngine.isThreadChangeNeeded()) {
            mGameEngine.post(new Runnable() {
                @Override
                public void run() {
                    cancel();
                }
            });
            return;
        }

        if (mInsertedTower != null) {
            mGameEngine.remove(mInsertedTower);

            hideTowerLevels();
            mCurrentPlateau = null;
            mInsertedTower = null;
        }
    }

    private void showTowerLevels() {
        Iterator<Tower> towers = mGameEngine.get(Types.TOWER).cast(Tower.class);

        while (towers.hasNext()) {
            Tower tower = towers.next();
            tower.showLevel();
        }
    }

    private void hideTowerLevels() {
        Iterator<Tower> towers = mGameEngine.get(Types.TOWER).cast(Tower.class);

        while (towers.hasNext()) {
            Tower tower = towers.next();
            tower.hideLevel();
        }
    }

}

package ch.logixisland.anuto.business.score;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class ScoreBoard {

    private int mCredits;
    private int mCreditsEarned;
    private int mLives;
    private int mEarlyBonus;
    private int mWaveBonus;

    private final List<CreditsListener> mCreditsListeners = new CopyOnWriteArrayList<>();
    private final List<LivesListener> mLivesListeners = new CopyOnWriteArrayList<>();
    private final List<BonusListener> mBonusListeners = new CopyOnWriteArrayList<>();

    public synchronized void reset(int lives, int credits) {
        mCredits = credits;
        mCreditsEarned = credits;
        mLives = lives;
        mEarlyBonus = 0;
        mWaveBonus = 0;

        creditsChanged();
        livesChanged();
        bonusChanged();
    }

    public synchronized void takeLives(int lives) {
        mLives -= lives;
        livesChanged();
    }

    public synchronized void giveCredits(int credits, boolean earned) {
        mCredits += credits;

        if (earned) {
            mCreditsEarned += credits;
        }

        creditsChanged();
    }

    public synchronized void takeCredits(int credits) {
        mCredits -= credits;
        creditsChanged();
    }

    public synchronized void setEarlyBonus(int earlyBonus) {
        mEarlyBonus = earlyBonus;
        bonusChanged();
    }

    public synchronized void setWaveBonus(int waveBonus) {
        mWaveBonus = waveBonus;
        bonusChanged();
    }

    public int getCredits() {
        return mCredits;
    }

    public int getCreditsEarned() {
        return mCreditsEarned;
    }

    public int getScore() {
        return mCreditsEarned;
    }

    public int getLives() {
        return mLives;
    }

    public int getEarlyBonus() {
        return mEarlyBonus;
    }

    public void addBonusListener(BonusListener listener) {
        mBonusListeners.add(listener);
    }

    public void removeBonusListener(BonusListener listener) {
        mBonusListeners.remove(listener);
    }

    public void addCreditsListener(CreditsListener listener) {
        mCreditsListeners.add(listener);
    }

    public void removeCreditsListener(CreditsListener listener) {
        mCreditsListeners.remove(listener);
    }

    public void addLivesListener(LivesListener listener) {
        mLivesListeners.add(listener);
    }

    public void removeLivesListener(LivesListener listener) {
        mLivesListeners.remove(listener);
    }

    private void bonusChanged() {
        for (BonusListener listener : mBonusListeners) {
            listener.bonusChanged(mWaveBonus, mEarlyBonus);
        }
    }

    private void creditsChanged() {
        for (CreditsListener listener : mCreditsListeners) {
            listener.creditsChanged(mCredits);
        }
    }

    private void livesChanged() {
        for (LivesListener listener : mLivesListeners) {
            listener.livesChanged(mLives);
        }
    }
}

package ch.logixisland.anuto.view.game;

import android.content.Context;
import android.graphics.Canvas;
import android.util.AttributeSet;
import android.view.DragEvent;
import android.view.MotionEvent;
import android.view.View;

import ch.logixisland.anuto.AnutoApplication;
import ch.logixisland.anuto.GameFactory;
import ch.logixisland.anuto.business.control.TowerInserter;
import ch.logixisland.anuto.business.control.TowerSelector;
import ch.logixisland.anuto.engine.render.Renderer;
import ch.logixisland.anuto.engine.render.Viewport;
import ch.logixisland.anuto.util.math.vector.Vector2;

public class GameView extends View implements View.OnDragListener, View.OnTouchListener {

    private final Viewport mViewport;
    private final Renderer mRenderer;
    private final TowerSelector mTowerSelector;
    private final TowerInserter mTowerInserter;

    public GameView(Context context, AttributeSet attrs) {
        super(context, attrs);

        if (!isInEditMode()) {
            GameFactory factory = AnutoApplication.getInstance().getGameFactory();
            mViewport = factory.getViewport();
            mRenderer = factory.getRenderer();
            mTowerSelector = factory.getTowerSelector();
            mTowerInserter = factory.getTowerInserter();

            mRenderer.setView(this);
        } else {
            mViewport = null;
            mRenderer = null;
            mTowerSelector = null;
            mTowerInserter = null;
        }

        setFocusable(true);
        setOnDragListener(this);
        setOnTouchListener(this);
    }

    public void close() {
        mRenderer.setView(null);
    }

    @Override
    public void onSizeChanged(int w, int h, int oldw, int oldh) {
        super.onSizeChanged(w, h, oldw, oldh);

        if (!isInEditMode()) {
            mViewport.setScreenSize(w, h);
        }
    }

    @Override
    public void onDraw(Canvas canvas) {
        super.onDraw(canvas);

        if (!isInEditMode()) {
            mRenderer.draw(canvas);
        }
    }

    @Override
    public boolean onTouch(View view, MotionEvent event) {
        if (event.getAction() == MotionEvent.ACTION_DOWN) {
            Vector2 pos = mViewport.screenToGame(new Vector2(event.getX(), event.getY()));
            mTowerSelector.selectTowerAt(pos);
            return true;
        }

        return false;
    }

    @Override
    public boolean onDrag(View view, DragEvent event) {
        if (event.getAction() == DragEvent.ACTION_DRAG_STARTED) {
            if (event.getLocalState() instanceof TowerView) {
                return true;
            }
        }

        if (event.getAction() == DragEvent.ACTION_DRAG_LOCATION) {
            Vector2 pos = mViewport.screenToGame(new Vector2(event.getX(), event.getY()));
            mTowerInserter.setPosition(pos);
        }

        if (event.getAction() == DragEvent.ACTION_DROP) {
            mTowerInserter.buyTower();
        }

        if (event.getAction() == DragEvent.ACTION_DRAG_EXITED) {
            mTowerInserter.cancel();
        }

        return false;
    }

}

package ch.logixisland.anuto.view.game;

import android.content.ClipData;
import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Matrix;
import android.graphics.Paint;
import android.graphics.Point;
import android.util.AttributeSet;
import android.view.DragEvent;
import android.view.MotionEvent;
import android.view.View;

import ch.logixisland.anuto.AnutoApplication;
import ch.logixisland.anuto.GameFactory;
import ch.logixisland.anuto.R;
import ch.logixisland.anuto.business.control.TowerInserter;
import ch.logixisland.anuto.business.score.CreditsListener;
import ch.logixisland.anuto.business.score.ScoreBoard;
import ch.logixisland.anuto.engine.theme.ThemeManager;
import ch.logixisland.anuto.entity.tower.Tower;
import ch.logixisland.anuto.entity.tower.TowerFactory;

public class TowerView extends View implements View.OnTouchListener, View.OnDragListener {

    private final static float TEXT_SIZE = 20f;
    private final static float DRAW_SIZE = 1.3f;

    private final ThemeManager mThemeManager;
    private final TowerInserter mTowerInserter;
    private final ScoreBoard mScoreBoard;
    private final TowerFactory mTowerFactory;

    private Tower mPreviewTower;
    private int mTextColor;
    private int mTextColorDisabled;

    private final Paint mPaintText;
    private final Matrix mScreenMatrix;

    private CreditsListener mCreditsListener = new CreditsListener() {
        @Override
        public void creditsChanged(int credits) {
            if (mPreviewTower != null) {
                if (credits >= mPreviewTower.getValue()) {
                    mPaintText.setColor(mTextColor);
                } else {
                    mPaintText.setColor(mTextColorDisabled);
                }

                TowerView.this.postInvalidate();
            }
        }
    };

    public TowerView(Context context, AttributeSet attrs) throws ClassNotFoundException {
        super(context, attrs);

        if (!isInEditMode()) {
            GameFactory factory = AnutoApplication.getInstance().getGameFactory();
            mThemeManager = factory.getThemeManager();
            mScoreBoard = factory.getScoreBoard();
            mTowerInserter = factory.getTowerInserter();
            mTowerFactory = factory.getTowerFactory();

            mScoreBoard.addCreditsListener(mCreditsListener);
            mTextColor = mThemeManager.getColor(R.attr.textColor);
            mTextColorDisabled = mThemeManager.getColor(R.attr.textDisabledColor);
        } else {
            mThemeManager = null;
            mScoreBoard = null;
            mTowerInserter = null;
            mTowerFactory = null;
        }

        float density = context.getResources().getDisplayMetrics().density;
        mPaintText = new Paint();
        mPaintText.setTextAlign(Paint.Align.CENTER);
        mPaintText.setTextSize(TEXT_SIZE * density);

        mScreenMatrix = new Matrix();

        setOnTouchListener(this);
        setOnDragListener(this);
    }

    @Override
    protected void onSizeChanged(int w, int h, int oldw, int oldh) {
        super.onSizeChanged(w, h, oldw, oldh);

        mScreenMatrix.reset();

        float tileSize = Math.min(w, h);
        mScreenMatrix.postTranslate(DRAW_SIZE / 2, DRAW_SIZE / 2);
        mScreenMatrix.postScale(tileSize / DRAW_SIZE, tileSize / DRAW_SIZE);

        float paddingLeft = (w - tileSize) / 2f;
        float paddingTop = (h - tileSize) / 2f;
        mScreenMatrix.postTranslate(paddingLeft, paddingTop);

        mScreenMatrix.postScale(1f, -1f);
        mScreenMatrix.postTranslate(0, h);
    }

    @Override
    protected void onDraw(Canvas canvas) {
        super.onDraw(canvas);

        if (mPreviewTower != null) {
            canvas.save();
            canvas.concat(mScreenMatrix);
            mPreviewTower.preview(canvas);
            canvas.restore();

            canvas.drawText(Integer.toString(mPreviewTower.getValue()),
                    getWidth() / 2,
                    getHeight() / 2 - (mPaintText.ascent() + mPaintText.descent()) / 2,
                    mPaintText);
        }
    }

    @Override
    public boolean onTouch(View view, MotionEvent event) {
        if (event.getAction() == MotionEvent.ACTION_DOWN) {
            mTowerInserter.insertTower(mPreviewTower.getName());

            View.DragShadowBuilder shadowBuilder = new View.DragShadowBuilder() {
                @Override
                public void onProvideShadowMetrics(Point shadowSize, Point shadowTouchPoint) {
                }

                @Override
                public void onDrawShadow(Canvas canvas) {
                }
            };

            ClipData data = ClipData.newPlainText("", "");
            startDrag(data, shadowBuilder, this, 0);
        }

        return false;
    }

    @Override
    public boolean onDrag(View view, DragEvent event) {
        if (event.getAction() == DragEvent.ACTION_DRAG_STARTED) {
            if (event.getLocalState() == this) {
                return true;
            }
        }

        if (event.getAction() == DragEvent.ACTION_DRAG_ENDED) {
            mTowerInserter.cancel();
        }

        return false;
    }

    public void setSlot(int slot) {
        mPreviewTower = mTowerFactory.createTower(slot);
        mCreditsListener.creditsChanged(mScoreBoard.getCredits());
        postInvalidate();
    }

    public void close() {
        mScoreBoard.removeCreditsListener(mCreditsListener);
    }

}

package ch.logixisland.anuto.business.control;

import java.util.Arrays;
import java.util.List;

import ch.logixisland.anuto.business.score.ScoreBoard;
import ch.logixisland.anuto.engine.logic.GameEngine;
import ch.logixisland.anuto.entity.Types;
import ch.logixisland.anuto.entity.plateau.Plateau;
import ch.logixisland.anuto.entity.tower.AimingTower;
import ch.logixisland.anuto.entity.tower.Tower;
import ch.logixisland.anuto.entity.tower.TowerFactory;
import ch.logixisland.anuto.entity.tower.TowerStrategy;

public class TowerControl {

    private final GameEngine mGameEngine;
    private final ScoreBoard mScoreBoard;
    private final TowerSelector mTowerSelector;
    private final TowerFactory mTowerFactory;

    public TowerControl(GameEngine gameEngine, ScoreBoard scoreBoard, TowerSelector towerSelector,
                        TowerFactory towerFactory) {
        mGameEngine = gameEngine;
        mScoreBoard = scoreBoard;
        mTowerSelector = towerSelector;
        mTowerFactory = towerFactory;
    }

    public void upgradeTower() {
        if (mGameEngine.isThreadChangeNeeded()) {
            mGameEngine.post(new Runnable() {
                @Override
                public void run() {
                    upgradeTower();
                }
            });
            return;
        }

        Tower selectedTower = mTowerSelector.getSelectedTower();
        if (selectedTower == null || !selectedTower.isUpgradeable()) {
            return;
        }

        int upgradeCost = selectedTower.getUpgradeCost();
        if (upgradeCost > mScoreBoard.getCredits()) {
            return;
        }

        mScoreBoard.takeCredits(upgradeCost);
        Tower upgradedTower = mTowerFactory.createTower(selectedTower.getUpgradeName());

        if (upgradedTower instanceof AimingTower && selectedTower instanceof AimingTower) {
            AimingTower aimingTower = (AimingTower) selectedTower;
            AimingTower aimingUpgraded = (AimingTower) upgradedTower;
            aimingUpgraded.setLockTarget(aimingTower.doesLockTarget());
            aimingUpgraded.setStrategy(aimingTower.getStrategy());
        }

        Plateau plateau = mGameEngine.get(Types.PLATEAU)
                .cast(Plateau.class)
                .filter(Plateau.occupiedBy(selectedTower))
                .first();

        upgradedTower.setValue(selectedTower.getValue() + upgradeCost);
        upgradedTower.setEnabled(true);
        plateau.setOccupant(upgradedTower);
        mGameEngine.add(upgradedTower);
        mTowerSelector.showTowerInfo(upgradedTower);

        selectedTower.remove();
    }

    public void enhanceTower() {
        if (mGameEngine.isThreadChangeNeeded()) {
            mGameEngine.post(new Runnable() {
                @Override
                public void run() {
                    enhanceTower();
                }
            });
            return;
        }

        Tower selectedTower = mTowerSelector.getSelectedTower();
        if (selectedTower != null && selectedTower.isEnhanceable()) {
            if (selectedTower.getEnhanceCost() <= mScoreBoard.getCredits()) {
                mScoreBoard.takeCredits(selectedTower.getEnhanceCost());
                selectedTower.enhance();
                mTowerSelector.updateTowerInfo();
            }
        }
    }

    public void cycleTowerStrategy() {
        if (mGameEngine.isThreadChangeNeeded()) {
            mGameEngine.post(new Runnable() {
                @Override
                public void run() {
                    cycleTowerStrategy();
                }
            });
            return;
        }

        Tower selectedTower = mTowerSelector.getSelectedTower();
        if (selectedTower instanceof AimingTower) {
            AimingTower tower = (AimingTower) selectedTower;

            List<TowerStrategy> values = Arrays.asList(TowerStrategy.values());
            int index = values.indexOf(tower.getStrategy()) + 1;
            if (index >= values.size()) {
                index = 0;
            }
            tower.setStrategy(values.get(index));
            mTowerSelector.updateTowerInfo();
        }
    }

    public void toggleLockTarget() {
        if (mGameEngine.isThreadChangeNeeded()) {
            mGameEngine.post(new Runnable() {
                @Override
                public void run() {
                    toggleLockTarget();
                }
            });
            return;
        }

        Tower selectedTower = mTowerSelector.getSelectedTower();
        if (selectedTower instanceof AimingTower) {
            AimingTower tower = (AimingTower) selectedTower;
            tower.setLockTarget(!tower.doesLockTarget());
            mTowerSelector.updateTowerInfo();
        }
    }

    public void sellTower() {
        if (mGameEngine.isThreadChangeNeeded()) {
            mGameEngine.post(new Runnable() {
                @Override
                public void run() {
                    sellTower();
                }
            });
            return;
        }

        Tower selectedTower = mTowerSelector.getSelectedTower();
        if (selectedTower != null) {
            mScoreBoard.giveCredits(selectedTower.getValue(), false);
            mGameEngine.remove(selectedTower);
        }
    }

}

